<?php
if (!defined('ABSPATH')) exit;
final class Dares_Piket_WhatsApp {
 const OPT='dares_piket_whatsapp';
 static function init(){add_action('admin_menu',[__CLASS__,'menu']);add_action('admin_post_dares_piket_wa_save',[__CLASS__,'save']);add_action('admin_post_dares_piket_wa_test',[__CLASS__,'test']);add_action('rest_api_init',[__CLASS__,'routes']);}
 static function opts(){return wp_parse_args((array)get_option(self::OPT,[]),['enabled'=>0,'token'=>'','phone_id'=>'','api_version'=>'v23.0','secret'=>'','verify'=>'','language'=>'nl','templates'=>['reminder'=>'dares_piket_herinnering','started'=>'dares_piket_gestart','transfer'=>'dares_piket_overdracht','change'=>'dares_piket_wijziging','other'=>'dares_piket_melding'],'people'=>[],'log'=>[]]);}
 static function recipient($str){$str=trim((string)$str);if(preg_match('/^\+?[0-9 ()-]{8,24}$/',$str))return preg_replace('/\D/','',$str);return preg_match('/^[A-Z]{2}\.[A-Za-z0-9]{1,128}$/',$str)?$str:'';}
 static function menu(){add_submenu_page('dares-piketrooster','WhatsApp Business','WhatsApp Business','manage_options','dares-piket-wa',[__CLASS__,'page']);}
 static function page(){if(!current_user_can('manage_options'))wp_die('Geen toegang');$o=self::opts();echo '<div class="wrap"><h1>WhatsApp Business — DARES Piketrooster</h1><p>Officiële Meta Cloud API. Een WhatsApp-gebruikersnaam is alleen een herkenningslabel: om te verzenden is een telefoonnummer of echte BSUID nodig. Verstuur alleen naar medewerkers met aantoonbare toestemming.</p>';
 if(isset($_GET['result']))echo '<div class="notice notice-info"><p>'.esc_html(sanitize_text_field(wp_unslash($_GET['result']))).'</p></div>';
 echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="dares_piket_wa_save">';wp_nonce_field('dares_piket_wa_save');echo '<table class="form-table"><tr><th>Automatische berichten</th><td><label><input name="enabled" type="checkbox" value="1" '.checked($o['enabled'],1,false).'> Inschakelen</label></td></tr>';
 foreach(['phone_id'=>'Meta Phone Number ID','api_version'=>'Graph API-versie','language'=>'Sjabloontaal','token'=>'Access token','secret'=>'Meta App Secret','verify'=>'Webhook verificatietoken'] as $key=>$label){$s=in_array($key,['token','secret','verify'],true);echo '<tr><th>'.esc_html($label).'</th><td><input autocomplete="off" class="regular-text" type="'.($s?'password':'text').'" name="'.esc_attr($key).'" value="'.($s?'':esc_attr($o[$key])).'" placeholder="'.($s&&!empty($o[$key])?'Al ingesteld — leeg laten om te behouden':'').'"></td></tr>';}
 foreach(['reminder'=>'Herinnering','started'=>'Dienst begint','transfer'=>'Overdracht','change'=>'Roosterwijziging','other'=>'Test/overige'] as $key=>$label)echo '<tr><th>Sjabloon: '.esc_html($label).'</th><td><input name="template['.esc_attr($key).']" value="'.esc_attr($o['templates'][$key]??'').'"></td></tr>';
 echo '</table><p>Maak deze templates eerst aan en laat ze goedkeuren in Meta. Elk sjabloon moet precies drie bodyparameters hebben: naam <code>{{1}}</code>, melding <code>{{2}}</code>, portaal-URL <code>{{3}}</code>.</p><h2>Medewerkers en toestemming</h2><table class="widefat striped"><thead><tr><th>Medewerker</th><th>Telefoonnummer met landcode / BSUID</th><th>WhatsApp-gebruikersnaam (label)</th><th>Opt-in</th></tr></thead><tbody>';
 foreach(Dares_Piketrooster::people() as $p){$r=$o['people'][$p->id]??[];echo '<tr><td>'.esc_html($p->name).'</td><td><input class="regular-text" name="recipient['.(int)$p->id.']" value="'.esc_attr($r['to']??'').'"></td><td><input name="username['.(int)$p->id.']" value="'.esc_attr($r['username']??'').'"></td><td><input type="checkbox" name="consent['.(int)$p->id.']" value="1" '.checked(!empty($r['consent']),true,false).'></td></tr>';}
 echo '</tbody></table><p><button class="button button-primary">Opslaan</button></p></form><hr><h2>WhatsApp testbericht</h2><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="dares_piket_wa_test">';wp_nonce_field('dares_piket_wa_test');echo '<select name="person_id">';foreach(Dares_Piketrooster::people() as $p)echo '<option value="'.(int)$p->id.'">'.esc_html($p->name).'</option>';echo '</select> <button class="button">Testbericht verzenden</button></form><p>Testen controleert API-acceptatie, geen uiteindelijke aflevering.</p>';
 echo '<h2>Meta webhook</h2><p>Callback: <code>'.esc_html(rest_url('dares-piket/v1/whatsapp-webhook')).'</code>. Stel webhook-verificatietoken en App Secret in; abonneer bij Meta op de messages-webhook.</p><h2>Logboek (maximaal 100)</h2><table class="widefat striped"><thead><tr><th>Tijd</th><th>Medewerker</th><th>Type</th><th>Status</th><th>Detail</th></tr></thead><tbody>';foreach($o['log'] as $l)echo '<tr><td>'.esc_html($l['at']).'</td><td>'.esc_html($l['person']).'</td><td>'.esc_html($l['event']).'</td><td>'.esc_html($l['status']).'</td><td>'.esc_html($l['detail']).'</td></tr>';echo '</tbody></table></div>';}
 static function redirect($s){wp_safe_redirect(add_query_arg(['page'=>'dares-piket-wa','result'=>$s],admin_url('admin.php')));exit;}
 static function save(){if(!current_user_can('manage_options'))wp_die('Geen toegang');check_admin_referer('dares_piket_wa_save');$o=self::opts();$o['enabled']=empty($_POST['enabled'])?0:1;foreach(['phone_id','api_version','language'] as $k)$o[$k]=sanitize_text_field(wp_unslash($_POST[$k]??''));if(!preg_match('/^v\d+\.\d+$/',$o['api_version']))$o['api_version']='v23.0';if(!preg_match('/^[a-z]{2}(?:_[A-Z]{2})?$/',$o['language']))$o['language']='nl';foreach(['token','secret','verify'] as $k){$v=trim((string)wp_unslash($_POST[$k]??''));if($v!=='')$o[$k]=sanitize_text_field($v);}foreach(['reminder','started','transfer','change','other'] as $k)$o['templates'][$k]=sanitize_key(wp_unslash($_POST['template'][$k]??''));$o['people']=[];foreach(Dares_Piketrooster::people() as $p){$id=(int)$p->id;$o['people'][$id]=['to'=>self::recipient(wp_unslash($_POST['recipient'][$id]??'')),'username'=>substr(sanitize_text_field(wp_unslash($_POST['username'][$id]??'')),0,128),'consent'=>!empty($_POST['consent'][$id])?1:0];}update_option(self::OPT,$o,false);self::redirect('Instellingen opgeslagen');}
 static function log($pid,$type,$status,$detail,$wamid=''){$o=self::opts();array_unshift($o['log'],['at'=>current_time('mysql'),'person'=>$pid,'event'=>$type,'status'=>$status,'detail'=>substr(sanitize_text_field($detail),0,160),'wamid'=>$wamid]);$o['log']=array_slice($o['log'],0,100);update_option(self::OPT,$o,false);}
 static function send($pid,$type,$message,$key){$o=self::opts();$r=$o['people'][$pid]??[];$to=self::recipient($r['to']??'');if(!$o['enabled']||!$to||empty($r['consent'])||!$o['token']||!$o['phone_id']||empty($o['templates'][$type]))return false;
 $dedup='dares_piket_wa_'.md5($pid.'|'.$key);if(get_option($dedup))return true;global $wpdb;$name=$wpdb->get_var($wpdb->prepare('SELECT name FROM '.$wpdb->prefix.'dares_piket_people WHERE id=%d',$pid));$params=[];foreach([substr($name?:'Medewerker',0,100),substr(preg_replace('/\s+/u',' ',wp_strip_all_tags($message)),0,950),Dares_Piket_Advanced::portal_url()] as $v)$params[]=['type'=>'text','text'=>$v];
 $payload=['messaging_product'=>'whatsapp','to'=>$to,'type'=>'template','template'=>['name'=>$o['templates'][$type],'language'=>['code'=>$o['language']],'components'=>[['type'=>'body','parameters'=>$params]]]];
 $url='https://graph.facebook.com/'.$o['api_version'].'/'.rawurlencode($o['phone_id']).'/messages';$res=wp_remote_post($url,['timeout'=>15,'redirection'=>0,'headers'=>['Authorization'=>'Bearer '.$o['token'],'Content-Type'=>'application/json'],'body'=>wp_json_encode($payload)]);
 if(is_wp_error($res)){self::log($pid,$type,'fout',$res->get_error_message());return false;}$code=wp_remote_retrieve_response_code($res);$body=json_decode(wp_remote_retrieve_body($res),true);$wamid=$body['messages'][0]['id']??'';if($code>=200&&$code<300&&$wamid){add_option($dedup,$wamid,'','no');self::log($pid,$type,'geaccepteerd','Wacht op afleverstatus',$wamid);return true;}self::log($pid,$type,'fout','HTTP '.$code.': '.($body['error']['message']??'geen message ID'));return false;}
 static function event($key,$pid,$subject,$body){$type='other';foreach(['reminder-'=>'reminder','started-'=>'started','transfer-'=>'transfer'] as $prefix=>$t)if(strpos($key,$prefix)===0){$type=$t;break;}self::send(absint($pid),$type,$subject.' — '.$body,$key);}
 static function roster_changed($before,$after){$ids=array_unique(array_filter([absint($before->person_id??0),absint($after->person_id??0)]));$key=md5(wp_json_encode([$before,$after]));foreach($ids as $pid)self::send($pid,'change','Je piketrooster is aangepast. Bekijk en bevestig je dienst in het portaal.','rooster-'.$key.'-'.$pid);}
 static function test(){if(!current_user_can('manage_options'))wp_die('Geen toegang');check_admin_referer('dares_piket_wa_test');$id=absint($_POST['person_id']??0);$ok=self::send($id,'other','Dit is een testbericht van het DARES Piketrooster.','test-'.wp_generate_uuid4());self::redirect($ok?'Meta heeft het testbericht geaccepteerd; controleer de status.':'Verzending mislukt of niet geconfigureerd; bekijk het logboek en de opt-in.');}
 static function routes(){register_rest_route('dares-piket/v1','/whatsapp-webhook',['methods'=>'GET','permission_callback'=>'__return_true','callback'=>[__CLASS__,'verify']]);register_rest_route('dares-piket/v1','/whatsapp-webhook',['methods'=>'POST','permission_callback'=>[__CLASS__,'signature'],'callback'=>[__CLASS__,'webhook']]);}
 static function verify($r){$o=self::opts();$token=$r->get_param('hub.verify_token');if($o['verify']&&$r->get_param('hub.mode')==='subscribe'&&is_string($token)&&hash_equals($o['verify'],$token))return new WP_REST_Response((string)$r->get_param('hub.challenge'),200,['Content-Type'=>'text/plain']);return new WP_Error('unauthorized','Verificatie mislukt',['status'=>403]);}
 static function signature($r){$s=self::opts()['secret'];$h=$r->get_header('x-hub-signature-256');return $s&&$h&&hash_equals('sha256='.hash_hmac('sha256',$r->get_body(),$s),$h);}
 static function webhook($r){$data=$r->get_json_params();foreach((array)($data['entry']??[]) as $entry)foreach((array)($entry['changes']??[]) as $change)foreach((array)($change['value']['statuses']??[]) as $status){$id=$status['id']??'';$state=sanitize_key($status['status']??'');if(!$id||!in_array($state,['sent','delivered','read','failed'],true))continue;$o=self::opts();foreach($o['log'] as &$line)if(($line['wamid']??'')===$id){$line['status']=$state;$line['detail']='Afleverstatus via webhook';break;}unset($line);update_option(self::OPT,$o,false);}return new WP_REST_Response(['ok'=>true],200);}
}
